package timodern;

import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.core.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.inventory.*;
import net.minecraft.resources.ResourceLocation;

@GameTestHolder("thaumicinfusion") @PrefixGameTestTemplate(false)
public class InfusionServerTests {
    @GameTest(template="test_empty",timeoutTicks=60) public static void configuredFlightInterval(GameTestHelper t){var l=t.getLevel();var pos=put(t,"volatus");int previous=InfusionConfig.VOLATUS_INTERVAL.get();InfusionConfig.VOLATUS_INTERVAL.set(4);var player=net.minecraftforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("4ae049f2-40b3-4518-9464-965dd6bc7749"),"TIFlightTest"));player.setPos(net.minecraft.world.phys.Vec3.atCenterOf(pos.above()));l.addFreshEntity(player);for(int tick=6;tick<=14;tick++)t.runAtTickTime(tick,()->t.assertTrue(player.getAbilities().mayfly,"Flight stays granted between configured four-tick samples"));t.runAtTickTime(15,()->player.setPos(net.minecraft.world.phys.Vec3.atCenterOf(pos.east(10))));t.runAtTickTime(22,()->{t.assertTrue(!player.getAbilities().mayfly,"Leaving the column revokes only infusion-owned flight after its sample interval");InfusionConfig.VOLATUS_INTERVAL.set(previous);player.discard();InfusionData.remove(l,pos);t.succeed();});}
    public static BlockPos put(GameTestHelper t,String... aspects){var p=t.absolutePos(new BlockPos(2,2,2));t.getLevel().setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());var e=new InfusionData.Entry();e.aspects.addAll(java.util.List.of(aspects));InfusionData.get(t.getLevel()).entries.put(p.asLong(),e);InfusionData.changed(t.getLevel(),p);return p;}
    @GameTest(template="test_empty") public static void positionalHooks(GameTestHelper t){var p=put(t,"lux","cognitio","messis","vitreus","spiritus","ordo","potentia","humanus");var l=t.getLevel();var s=l.getBlockState(p);
        t.assertTrue(s.getLightEmission(l,p)==14,"Lux light is position-specific");t.assertTrue(s.getEnchantPowerBonus(l,p)==1,"Cognitio bookshelf power");t.assertTrue(s.isFertile(l,p),"Messis fertility");t.assertTrue(s.getLightBlock(l,p)==0,"Vitreus passes light");t.assertTrue(s.getCollisionShape(l,p).isEmpty(),"Spiritus removes collision");t.assertTrue(s.getDestroySpeed(l,p)<0,"Humanus prevents mining");t.assertTrue(s.getSignal(l,p,Direction.UP)==15,"Potentia redstone 15");t.assertTrue(s.getDirectSignal(l,p,Direction.UP)==15,"Potentia strong redstone 15");t.assertTrue(!s.isValidSpawn(l,p,EntityType.ZOMBIE),"Bestia/humanus prevent spawns");t.assertTrue(((thaumcraft.api.crafting.IInfusionStabiliser)s.getBlock()).canStabiliseInfusion(l,p),"Ordo stabilises actual altar API");
        var ordinary=p.east();l.setBlockAndUpdate(ordinary,s);t.assertTrue(s.getLightEmission(l,ordinary)==0&&!s.getCollisionShape(l,ordinary).isEmpty()&&s.getDestroySpeed(l,ordinary)>0,"Adjacent same registry state remains ordinary");InfusionData.remove(l,p);t.succeed();}
    @GameTest(template="test_empty") public static void persistentAspectLinks(GameTestHelper t){var p=put(t,"iter","fabrico");var l=t.getLevel();var e=InfusionData.at(l,p);e.settings.putInt("tint",0x123456);InfusionRuntime.putDestination(e.settings,"iter",l,p.east(2));var copy=InfusionData.load(InfusionData.get(l).save(new net.minecraft.nbt.CompoundTag()));var restored=copy.entries.get(p.asLong());t.assertTrue(restored.aspects.equals(e.aspects)&&restored.settings.equals(e.settings),"Aspect settings and link position persist together");InfusionData.remove(l,p);t.succeed();}
    @GameTest(template="test_empty") public static void reciprocalLinkTeleport(GameTestHelper t){var p=put(t,"iter");var l=t.getLevel();var q=p.east(3);l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());var e2=new InfusionData.Entry();e2.aspects.add("iter");InfusionData.get(l).entries.put(q.asLong(),e2);var player=net.minecraftforge.common.util.FakePlayerFactory.getMinecraft(l);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.PAPER));t.assertTrue(InfusionRuntime.link(l,p,player,net.minecraft.world.InteractionHand.MAIN_HAND),"First paper binding");t.assertTrue(player.getMainHandItem().is(ThaumicInfusion.PAPER.get()),"Bound paper item");InfusionRuntime.link(l,q,player,net.minecraft.world.InteractionHand.MAIN_HAND);t.assertTrue(InfusionRuntime.destination(l,InfusionData.at(l,p),"iter").pos().equals(q)&&InfusionRuntime.destination(l,e2,"iter").pos().equals(p),"Reciprocal link coordinates are preserved");InfusionData.remove(l,p);InfusionData.remove(l,q);t.succeed();}
    @GameTest(template="test_empty") public static void essentiaRecipes(GameTestHelper t){var recipe=t.getLevel().getRecipeManager().byKey(new ResourceLocation("thaumicinfusion","essentia_block")).orElseThrow();var grid=new TransientCraftingContainer(new AbstractContainerMenu(null,0){public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}},3,3);var terra=tc4revival.aspect.TCAspects.catalog().require("terra");for(int slot:new int[]{0,1,3,4})grid.setItem(slot,tc4revival.content.EssentiaPhialItem.filled(terra));var r=(EssentiaRecipe)recipe;t.assertTrue(r.matches(grid,t.getLevel()),"Four matching full phials form a square recipe");t.assertTrue(EssentiaBlock.aspect(r.assemble(grid,t.getLevel().registryAccess())).equals("terra"),"Recipe result retains phial aspect");grid.setItem(4,tc4revival.content.EssentiaPhialItem.filled(tc4revival.aspect.TCAspects.catalog().require("ignis")));t.assertTrue(!r.matches(grid,t.getLevel()),"Mixed aspects cannot craft");t.succeed();}
    @GameTest(template="test_empty") public static void itemAttractionAndFreezing(GameTestHelper t){var p=put(t,"lucrum","gelum");var l=t.getLevel();var item=new ItemEntity(l,p.getX()+3.5,p.getY()+1,p.getZ()+3.5,new ItemStack(Items.IRON_INGOT));l.addFreshEntity(item);InfusionRuntime.effect(l,p,InfusionData.at(l,p),"lucrum",new java.util.HashSet<>());t.assertTrue(item.getDeltaMovement().x<0&&item.getDeltaMovement().z<0,"Lucrum pulls items horizontally toward infused block");var freezeOrigin=p.above(20);var first=freezeOrigin.offset(-10,-10,-10);l.setBlockAndUpdate(first,Blocks.WATER.defaultBlockState());InfusionRuntime.freeze(l,freezeOrigin);t.assertTrue(l.getBlockState(first).is(Blocks.ICE),"Gelum freezes its original first candidate");item.discard();InfusionData.remove(l,p);t.succeed();}
    @GameTest(template="test_empty",timeoutTicks=100) public static void fallingCarriesInfusion(GameTestHelper t){var p=put(t,"terra","lux");var l=t.getLevel();l.setBlockAndUpdate(p.below(),Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p.below(2),Blocks.STONE.defaultBlockState());InfusionRuntime.effect(l,p,InfusionData.at(l,p),"terra",new java.util.HashSet<>());t.runAtTickTime(30,()->{t.assertTrue(l.getBlockState(p.below()).is(Blocks.STONE)&&InfusionData.has(l,p.below(),"lux"),"Falling block retains positional aspects after landing");InfusionData.remove(l,p.below());t.succeed();});}
    @GameTest(template="test_empty") public static void machineAndPermutationLinks(GameTestHelper t){var l=t.getLevel();var p=put(t,"machina","permutatio");var q=p.east(3);l.setBlockAndUpdate(q,Blocks.CHEST.defaultBlockState());var right=new InfusionData.Entry();right.aspects.addAll(java.util.List.of("machina","permutatio"));InfusionData.get(l).entries.put(q.asLong(),right);for(String a:java.util.List.of("machina","permutatio")){InfusionRuntime.putDestination(InfusionData.at(l,p).settings,a,l,q);InfusionRuntime.putDestination(right.settings,a,l,p);}l.setBlockAndUpdate(q.north(),Blocks.REDSTONE_BLOCK.defaultBlockState());t.assertTrue(InfusionRuntime.signal(l,p)==15,"Machina relays remote adjacent redstone");var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(q);chest.setItem(0,new ItemStack(Items.DIAMOND,3));InfusionRuntime.swap(l,p,l,q);t.assertTrue(l.getBlockState(p).is(Blocks.CHEST)&&((net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(p)).getItem(0).getCount()==3,"Permutation retains block entity inventory");t.assertTrue(InfusionData.has(l,p,"permutatio")&&InfusionData.has(l,q,"permutatio"),"Position infusions remain bound at both coordinates");InfusionData.remove(l,p);InfusionData.remove(l,q);t.succeed();}
    @GameTest(template="test_empty") public static void contactEffectsAndProtection(GameTestHelper t){var l=t.getLevel();var p=put(t,"aer","venenum","infernus","vinculum","pannus","volatus");var player=net.minecraftforge.common.util.FakePlayerFactory.get(l,new com.mojang.authlib.GameProfile(java.util.UUID.fromString("eeb8e9a6-e544-438f-bb07-abcbb946ba63"),"TIContactTest"));player.setPos(net.minecraft.world.phys.Vec3.atCenterOf(p.above()));l.addFreshEntity(player);var entry=InfusionData.at(l,p);var flying=new java.util.HashSet<java.util.UUID>();for(String a:java.util.List.of("aer","venenum","infernus"))InfusionRuntime.effect(l,p,entry,a,flying);t.assertTrue(player.hasEffect(net.minecraft.world.effect.MobEffects.JUMP)&&player.hasEffect(net.minecraft.world.effect.MobEffects.POISON)&&player.isOnFire(),"Original contact status effects");player.setDeltaMovement(1,1,1);InfusionRuntime.effect(l,p,entry,"vinculum",flying);t.assertTrue(player.getDeltaMovement().equals(net.minecraft.world.phys.Vec3.ZERO),"Vinculum immobilises entities");player.fallDistance=20;InfusionRuntime.effect(l,p,entry,"pannus",flying);t.assertTrue(player.fallDistance==0,"Pannus clears fall distance");InfusionRuntime.effect(l,p,entry,"volatus",flying);t.assertTrue(flying.contains(player.getUUID()),"Volatus column grants flight");player.discard();InfusionData.remove(l,p);t.succeed();}
}
